package de.fitnesscoach.agent;
import static org.junit.Assert.*;import java.time.*;import org.json.JSONObject;import org.junit.Test;import de.fitnesscoach.data.entity.*;
public class CoachContextBuilderTest{
 @Test public void onlyAllowListedSectionsAreSerialized()throws Exception{AgentTestRepository r=new AgentTestRepository();DailyHealthEntity h=new DailyHealthEntity();h.date=LocalDate.now();h.restingHeartRate=55d;h.restingHeartRateQuality=DomainEnums.DataQuality.AVAILABLE;r.saveDailyHealth(h);JSONObject x=new CoachContextBuilder(r).build(LocalDate.now());assertEquals(6,x.length());assertTrue(x.has("profile"));assertTrue(x.has("goal"));assertTrue(x.has("today"));assertTrue(x.has("recentTraining"));assertTrue(x.has("baselines"));assertTrue(x.has("memories"));String raw=x.toString();assertFalse(raw.contains("externalRecordId"));assertFalse(raw.contains("averageHeartRate"));assertFalse(raw.contains("rawHeartRate"));}
 @Test public void missingDataIsExplicitAndNotZero()throws Exception{JSONObject x=new CoachContextBuilder(new AgentTestRepository()).build(LocalDate.now());assertEquals("unavailable",x.getJSONObject("today").getJSONObject("health").getString("availability"));assertFalse(x.toString().contains("\"sleepMinutes\":0"));}
 @Test public void debugSummaryDoesNotDumpMeasurements()throws Exception{AgentTestRepository r=new AgentTestRepository();DailyHealthEntity h=new DailyHealthEntity();h.date=LocalDate.now();h.restingHeartRate=57d;r.saveDailyHealth(h);String s=new CoachContextBuilder(r).debugSummary(LocalDate.now());assertFalse(s.contains("57"));assertTrue(s.contains("allow-list"));}
 @Test public void debugSummaryDoesNotAccessRepository(){String s=new CoachContextBuilder(null).debugSummary(LocalDate.now());assertTrue(s.contains("profile"));assertTrue(s.contains("today"));assertTrue(s.contains("memories"));}
}
